static void drop_S_Ctx(T_Ctx *p) { drop_Str(&p->f_path); drop_L_Str(&p->f_lines); }
static void drop_S_Tok(T_Tok *p) { drop_Str(&p->f_k); drop_Str(&p->f_v); }
static void drop_S_Node(T_Node *p) { drop_Str(&p->f_k); drop_Str(&p->f_name); drop_Str(&p->f_name2); drop_Str(&p->f_op); drop_Str(&p->f_v); drop_Str(&p->f_ty); drop_Str(&p->f_ret); drop_L_S_Node(&p->f_kids); drop_L_Str(&p->f_names); }
static void drop_S_Parser(T_Parser *p) { drop_S_Ctx(&p->f_ctx); drop_L_S_Tok(&p->f_toks); }
static void drop_S_Frz(T_Frz *p) { drop_Str(&p->f_mode); }
static void drop_S_Var(T_Var *p) { drop_Str(&p->f_name); drop_Str(&p->f_ty); drop_Str(&p->f_cname); drop_Str(&p->f_kind); drop_Str(&p->f_state); drop_L_S_Frz(&p->f_frozen); }
static void drop_S_Scope(T_Scope *p) { drop_M3_StrInt(&p->f_vars); drop_L_Int(&p->f_order); drop_L_Int(&p->f_unfreeze); }
static void drop_S_Place(T_Place *p) { drop_Str(&p->f_code); drop_Str(&p->f_ty); }
static void drop_S_CT(T_CT *p) { drop_Str(&p->f_code); drop_Str(&p->f_ty); }
static void drop_S_GR(T_GR *p) { drop_Str(&p->f_code); drop_Str(&p->f_ty); drop_S_Place(&p->f_p); }
static void drop_S_Fld(T_Fld *p) { drop_Str(&p->f_name); drop_Str(&p->f_ty); }
